                if (_playerTokenIds[i - 1] >= _playerTokenIds[i]) revert UNSORTED_OR_DUPLICATE_TOKEN_IDS();
                thisAddressArray[i] = address(this);
            }
            return playerToken.balanceOfBatch(thisAddressArray, _playerTokenIds);
        }
    }

