    function _emitFeeBreakdown(
        address _user,
        uint256[] memory _playerTokenIds,
        uint256[] memory _feeRateBps,
        int256[] memory _discountFeeBps
    ) internal {
        uint256[] memory effectiveFeeBps = new uint256[](_playerTokenIds.length);
